import java.util.Scanner;
import java.io.File;
import java.nio.file.FileSystems;

public class CompangeSys {
    public static void main (String[] args) {
        System.out.println("CompangeSys - Company Management System On");

        // loading company info
        String dataCompany = "company";
        String PathCompany = FileSystems.getDefault().getPath(System.getProperty("user.dir"),"src","Data", dataCompany + ".txt").toAbsolutePath().toString();
        File fileCompany = new File(PathCompany);

        // read company data into an array
        String[] companyData = new String[6];
        try {
            Scanner scannerCompany = new Scanner(fileCompany);
            int line_num = 0;
            while (scannerCompany.hasNextLine() && line_num < 6) {
                String line = scannerCompany.nextLine();
                int colonIndex = line.indexOf(":");
                if (colonIndex != -1) {
                    companyData[line_num] = line.substring(colonIndex + 1).trim();
                }
                line_num++;
            }
            scannerCompany.close();
        } catch (Exception e) {
            System.out.println("Error reading company file: " + e.getMessage());
        }
        System.out.println("Company Info Has Been Loaded.");

        // loading employees info
        String dataEmployees = "employees";
        String pathEmployees = FileSystems.getDefault().getPath(System.getProperty("user.dir"),"src","Data", dataEmployees + ".txt").toAbsolutePath().toString();
        File fileEmployees = new File(pathEmployees);

        // data structure - table for employees
        int numEmployees = 8, numEntries = 6;
        String[][] employees = new String[numEmployees][numEntries+1];

        try {
            Scanner scanner = new Scanner(fileEmployees);
            int row = 0;
            while (scanner.hasNextLine() && row < numEmployees) {
                String line = scanner.nextLine();
                String[] parts = line.split(",");
                // Trim spaces and put data into your 2D array
                for (int col = 0; col < parts.length && col <= numEntries; col++) {
                    employees[row][col] = parts[col].trim();
                }
                row++;
            }
            scanner.close();
        } catch (Exception e) {
            System.out.println("Error reading file: " + e.getMessage());
        }
        System.out.println("Employee Info Is Ready.");

        if (args.length > 0) {
            if (args[0].equals("employees")) {
                System.out.println("[EMPLOYEES]");
                printEmployees(employees);
            }
            else if (args[0].equals("summary")) {
                System.out.println("[SUMMARY]");
                summarizeCompany(companyData, employees);
            }
            else {
                System.out.println("You Need to Enter a Proper Argument");
            }
        }
    }

    // print the EMPLOYEES table
    public static void printEmployees (String[][] employees) {
        System.out.printf("%-30.28s %-20.18s %-6s %-20.18s %-20.18s %-5s\n", "Name", "Title", "Year", "Department", "Skills", "Points");
        // Loop through each employee and print their data dynamically
        for (int i = 0; i < employees.length; i++) {
            if (employees[i][0] != null) {  // Check if row has data
                System.out.printf("%-30.28s %-20.18s %-6s %-20.18s %-20.18s %-5s\n",
                    employees[i][0],  // Name
                    employees[i][1],  // Title
                    employees[i][3],  // Hire Year
                    employees[i][4],  // Department
                    employees[i][5],  // Skills
                    employees[i][6]   // Points
                );
            }
        }
    }

    // print the SUMMARY of the company
    public static void summarizeCompany (String[] companyData, String[][] employees) {
        // display company info from company.txt
        System.out.printf("%-25s %s\n", "Name:", companyData[0]);
        System.out.printf("%-25s %s\n", "Founded Year:", companyData[1]);
        System.out.printf("%-25s %s\n", "CEO:", companyData[2]);
        System.out.printf("%-25s %s\n", "Number of Employees:", companyData[4]);
        System.out.printf("%-25s %s\n", "Number of Departments:", companyData[3]);

        // dynamically count employees per department
        String[] departments = new String[employees.length];
        int[] deptCounts = new int[employees.length];
        int numDepts = 0;

        for (int i = 0; i < employees.length; i++) {
            if (employees[i][4] != null) {
                String dept = employees[i][4];
                boolean found = false;
                for (int j = 0; j < numDepts; j++) {
                    if (departments[j].equals(dept)) {
                        deptCounts[j]++;
                        found = true;
                        break;
                    }
                }
                if (!found) {
                    departments[numDepts] = dept;
                    deptCounts[numDepts] = 1;
                    numDepts++;
                }
            }
        }

        System.out.println();
        System.out.printf("%-20.18s %-4s\n", "Departments", "# of Employees");
        for (int i = 0; i < numDepts; i++) {
            System.out.printf("%-20.18s %-4d\n", departments[i], deptCounts[i]);
        }
    }
