package com.adtpractice.service;

import com.adtpractice.model.Challenge;
import com.adtpractice.model.ExecutionDto.ExecuteResponse;
import jdk.jshell.JShell;
import jdk.jshell.SnippetEvent;
import jdk.jshell.Snippet;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.util.List;
import java.util.concurrent.*;

/**
 * Evaluates user-submitted Java code using the JShell API.
 *
 * How it works:
 *  1. Creates a fresh JShell instance per execution (isolation).
 *  2. Feeds the user's code into JShell.
 *  3. If a challengeId is provided, appends the challenge's test code.
 *  4. Captures stdout and compares against expected output.
 *  5. Enforces a timeout to prevent infinite loops.
 */
@Service
public class JShellExecutionService {

    private static final Logger log = LoggerFactory.getLogger(JShellExecutionService.class);

    @Value("${app.jshell.timeout-seconds:5}")
    private int timeoutSeconds;

    @Value("${app.jshell.max-output-length:10000}")
    private int maxOutputLength;

    private final ExecutorService executor = Executors.newCachedThreadPool();

    /**
     * Execute raw code (no challenge validation).
     */
    public ExecuteResponse execute(String code) {
        return executeWithTimeout(code, null);
    }

    /**
     * Execute user code + challenge test code, then validate output.
     */
    public ExecuteResponse executeChallenge(String userCode, Challenge challenge) {
        String fullCode = userCode + "\n" + challenge.getTestCode();
        ExecuteResponse response = executeWithTimeout(fullCode, challenge.getExpectedOutput());
        return response;
    }

    private ExecuteResponse executeWithTimeout(String code, String expectedOutput) {
        long start = System.currentTimeMillis();

        Future<ExecuteResponse> future = executor.submit(() -> runInJShell(code, expectedOutput));

        try {
            return future.get(timeoutSeconds, TimeUnit.SECONDS);
        } catch (TimeoutException e) {
            future.cancel(true);
            long elapsed = System.currentTimeMillis() - start;
            return new ExecuteResponse(false, "", "Execution timed out after " + timeoutSeconds + " seconds.", false, elapsed);
        } catch (Exception e) {
            long elapsed = System.currentTimeMillis() - start;
            return new ExecuteResponse(false, "", "Execution error: " + e.getMessage(), false, elapsed);
        }
    }

    private ExecuteResponse runInJShell(String code, String expectedOutput) {
        long start = System.currentTimeMillis();
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        PrintStream out = new PrintStream(baos);

        try (JShell jshell = JShell.builder().out(out).err(out).build()) {

            // Add common imports
            jshell.eval("import java.util.*;");
            jshell.eval("import java.util.stream.*;");

            // Evaluate user code
            List<SnippetEvent> events = jshell.eval(code);

            // Check for errors
            StringBuilder errors = new StringBuilder();
            for (SnippetEvent event : events) {
                if (event.status() == Snippet.Status.REJECTED) {
                    errors.append("Error: ").append(event.toString()).append("\n");
                }
                if (event.exception() != null) {
                    errors.append("Exception: ").append(event.exception().getMessage()).append("\n");
                }
            }

            out.flush();
            String output = baos.toString().trim();
            if (output.length() > maxOutputLength) {
                output = output.substring(0, maxOutputLength) + "\n... (output truncated)";
            }

            long elapsed = System.currentTimeMillis() - start;

            if (!errors.isEmpty()) {
                return new ExecuteResponse(false, output, errors.toString().trim(), false, elapsed);
            }

            boolean testsPassed = expectedOutput != null && output.equals(expectedOutput.trim());
            return new ExecuteResponse(true, output, null, expectedOutput == null || testsPassed, elapsed);

        } catch (Exception e) {
            long elapsed = System.currentTimeMillis() - start;
            log.error("JShell execution failed", e);
            return new ExecuteResponse(false, "", e.getMessage(), false, elapsed);
        }
    }
}

