package com.adtpractice.service;

import com.adtpractice.model.Challenge;
import jakarta.persistence.EntityManager;
import jakarta.persistence.PersistenceContext;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.Optional;

/**
 * Service layer for challenge management.
 */
@Service
@Transactional(readOnly = true)
public class ChallengeService {

    @PersistenceContext
    private EntityManager em;

    public List<Challenge> findAll() {
        return em.createQuery("SELECT c FROM Challenge c ORDER BY c.adtType, c.sortOrder", Challenge.class)
                 .getResultList();
    }

    public List<Challenge> findByAdtType(String adtType) {
        return em.createQuery("SELECT c FROM Challenge c WHERE c.adtType = :type ORDER BY c.sortOrder", Challenge.class)
                 .setParameter("type", adtType.toUpperCase())
                 .getResultList();
    }

    public Optional<Challenge> findById(Long id) {
        return Optional.ofNullable(em.find(Challenge.class, id));
    }

    /** Returns distinct ADT types that have challenges. */
    public List<String> getAvailableAdtTypes() {
        return em.createQuery("SELECT DISTINCT c.adtType FROM Challenge c ORDER BY c.adtType", String.class)
                 .getResultList();
    }

    @Transactional
    public Challenge save(Challenge challenge) {
        if (challenge.getId() == null) {
            em.persist(challenge);
            return challenge;
        }
        return em.merge(challenge);
    }
}

