/**
 * REST endpoints for browsing challenges.
 *
 * GET  /api/challenges              — list all challenges
 * GET  /api/challenges?adt=STACK    — filter by ADT type
 * GET  /api/challenges/{id}         — get single challenge
 * GET  /api/challenges/types        — get available ADT types
 */
