package com.adtpractice.controller;

import com.adtpractice.model.Challenge;
import com.adtpractice.model.ExecutionDto.ExecuteRequest;
import com.adtpractice.model.ExecutionDto.ExecuteResponse;
import com.adtpractice.service.ChallengeService;
import com.adtpractice.service.JShellExecutionService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

/**
 * POST /api/execute — run user code through JShell.
 *
 * If a challengeId is included, the challenge's test code is appended
 * and output is validated against expected results.
 */
@RestController
@RequestMapping("/api/execute")
public class ExecutionController {

    private final JShellExecutionService jshellService;
    private final ChallengeService challengeService;

    public ExecutionController(JShellExecutionService jshellService, ChallengeService challengeService) {
        this.jshellService = jshellService;
        this.challengeService = challengeService;
    }

    @PostMapping
    public ResponseEntity<ExecuteResponse> execute(@RequestBody ExecuteRequest request) {
        if (request.code() == null || request.code().isBlank()) {
            return ResponseEntity.badRequest()
                    .body(new ExecuteResponse(false, "", "No code provided.", false, 0));
        }

        // Sandbox mode (no challenge) — just run the code
        if (request.challengeId() == null) {
            return ResponseEntity.ok(jshellService.execute(request.code()));
        }

        // Challenge mode — run code + test, validate output
        Challenge challenge = challengeService.findById(request.challengeId())
                .orElse(null);

        if (challenge == null) {
            return ResponseEntity.badRequest()
                    .body(new ExecuteResponse(false, "", "Challenge not found.", false, 0));
        }

        return ResponseEntity.ok(jshellService.executeChallenge(request.code(), challenge));
    }
}

