            // TODO: push characters onto the stack

            // TODO: pop characters to build reversed string
            StringBuilder reversed = new StringBuilder();

            System.out.println(reversed.toString());
            """,
            """
            // Test validation
            String testInput = "hello";
            Stack<Character> testStack = new Stack<>();
            for (char c : testInput.toCharArray()) testStack.push(c);
            StringBuilder testResult = new StringBuilder();
            while (!testStack.isEmpty()) testResult.append(testStack.pop());
            System.out.println(testResult.toString());
            """,
            "olleh"
        );

        seed("STACK", "Balanced Parentheses", "MEDIUM", 2,
            "Check if a string of brackets `()[]{}` is balanced using a Stack.",
            """
            // Given: String expr = "({[]})";
            // Return true if balanced, false otherwise.
            String expr = "({[]})";
            Stack<Character> stack = new Stack<>();
            boolean balanced = true;

            // TODO: iterate through expr, push opening brackets, pop and match closing brackets

            System.out.println(balanced && stack.isEmpty());
            """,
            """
            String testExpr = "({[]})";
            Stack<Character> s = new Stack<>();
            boolean bal = true;
            for (char c : testExpr.toCharArray()) {
                if (c == '(' || c == '[' || c == '{') s.push(c);
                else {
                    if (s.isEmpty()) { bal = false; break; }
                    char top = s.pop();
                    if ((c == ')' && top != '(') || (c == ']' && top != '[') || (c == '}' && top != '{'))
                        { bal = false; break; }
                }
            }
            System.out.println(bal && s.isEmpty());
            """,
            "true"
        );

        // --- QUEUE challenges ---
        seed("QUEUE", "Print Queue Simulator", "EASY", 1,
            "Simulate a print queue: enqueue 5 documents, then dequeue and print them in order.",
            """
            Queue<String> printQueue = new LinkedList<>();
            // TODO: add 5 documents to the queue
            // Hint: printQueue.offer("Doc1");

            // TODO: process (dequeue) and print each document
            """,
            """
            Queue<String> q = new LinkedList<>();
            q.offer("Doc1"); q.offer("Doc2"); q.offer("Doc3"); q.offer("Doc4"); q.offer("Doc5");
            while (!q.isEmpty()) System.out.println(q.poll());
            """,
            "Doc1\nDoc2\nDoc3\nDoc4\nDoc5"
        );

        // --- HASHMAP challenges ---
        seed("HASHMAP", "Word Frequency Counter", "EASY", 1,
            "Count the frequency of each word in the sentence using a `HashMap<String, Integer>`.",
            """
            String sentence = "the cat sat on the mat the cat";
            HashMap<String, Integer> freq = new HashMap<>();

            // TODO: split sentence into words and count each word's frequency

            // Print the frequency of "the"
            System.out.println(freq.get("the"));
            """,
            """
            String s = "the cat sat on the mat the cat";
            HashMap<String, Integer> f = new HashMap<>();
            for (String w : s.split(" ")) f.merge(w, 1, Integer::sum);
            System.out.println(f.get("the"));
            """,
            "3"
        );

        seed("HASHMAP", "Two Sum", "MEDIUM", 2,
            "Given an array of integers and a target, find indices of two numbers that add up to the target. Use a HashMap for O(n) lookup.",
            """
            int[] nums = {2, 7, 11, 15};
            int target = 9;
            HashMap<Integer, Integer> map = new HashMap<>();
            int[] result = new int[2];

            // TODO: iterate nums, check if (target - nums[i]) exists in map
            // Store result indices in result[0] and result[1]

            System.out.println(result[0] + "," + result[1]);
            """,
            """
            int[] nums = {2, 7, 11, 15};
            int target = 9;
            HashMap<Integer, Integer> m = new HashMap<>();
            int[] res = new int[2];
            for (int i = 0; i < nums.length; i++) {
                int complement = target - nums[i];
                if (m.containsKey(complement)) { res[0] = m.get(complement); res[1] = i; break; }
                m.put(nums[i], i);
            }
            System.out.println(res[0] + "," + res[1]);
            """,
            "0,1"
        );

        // --- LINKEDLIST challenges ---
        seed("LINKEDLIST", "Build and Traverse", "EASY", 1,
            "Add elements to a LinkedList and iterate through them.",
            """
            LinkedList<Integer> list = new LinkedList<>();
            // TODO: add numbers 1 through 5

            // TODO: iterate and print each element on its own line
            """,
            """
            LinkedList<Integer> list = new LinkedList<>();
            for (int i = 1; i <= 5; i++) list.add(i);
            for (int n : list) System.out.println(n);
            """,
            "1\n2\n3\n4\n5"
        );

        log.info("Seeded {} challenges.", challengeService.findAll().size());
    }

    private void seed(String adt, String title, String difficulty, int order,
                      String description, String starterCode, String testCode, String expectedOutput) {
        Challenge c = new Challenge();
        c.setAdtType(adt);
        c.setTitle(title);
        c.setDifficulty(difficulty);
        c.setSortOrder(order);
        c.setDescription(description);
        c.setStarterCode(starterCode);
        c.setTestCode(testCode);
        c.setExpectedOutput(expectedOutput);
        challengeService.save(c);
    }
}

