    type: 'STACK',
    name: 'Stack',
    icon: Layers,
    color: 'bg-blue-500',
    description: 'Last-In, First-Out (LIFO). Push, pop, and peek operations.',
    timeComplexity: 'O(1) push/pop',
  },
  {
    type: 'QUEUE',
    name: 'Queue',
    icon: ListOrdered,
    color: 'bg-green-500',
    description: 'First-In, First-Out (FIFO). Offer, poll, and peek operations.',
    timeComplexity: 'O(1) enqueue/dequeue',
  },
  {
    type: 'HASHMAP',
    name: 'HashMap',
    icon: Hash,
    color: 'bg-purple-500',
    description: 'Key-value pairs with O(1) average lookup. Hashing fundamentals.',
