import { useState } from 'react';
import { Play, CheckCircle2, XCircle, Loader2 } from 'lucide-react';
import CodeEditor from '../CodeEditor/CodeEditor';
import { executeCode } from '../../utils/api';

/**
 * Full challenge UI: description + editor + run button + output.
 *
 * Props:
 *   challenge - challenge object from the API
 */
export default function ChallengePanel({ challenge }) {
  const [code, setCode] = useState(challenge?.starterCode || '');
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  async function handleRun() {
    setLoading(true);
    setResult(null);
    try {
      const res = await executeCode(code, challenge.id);
      setResult(res);
    } catch (err) {
      setResult({ success: false, error: err.message, output: '', allTestsPassed: false });
    } finally {
      setLoading(false);
    }
  }

  if (!challenge) return null;

  return (
    <div className="space-y-4">
      {/* Challenge header */}
      <div className="bg-surface-800 rounded-xl p-5">
        <div className="flex items-center gap-3 mb-2">
          <h2 className="text-lg font-semibold text-white">{challenge.title}</h2>
          <span className={`text-xs px-2 py-0.5 rounded font-medium ${
            challenge.difficulty === 'EASY' ? 'bg-green-500/10 text-green-400' :
            challenge.difficulty === 'MEDIUM' ? 'bg-yellow-500/10 text-yellow-400' :
            'bg-red-500/10 text-red-400'
          }`}>
            {challenge.difficulty}
          </span>
        </div>
        <p className="text-gray-400 text-sm leading-relaxed">{challenge.description}</p>
      </div>

      {/* Code editor */}
      <CodeEditor value={code} onChange={(val) => setCode(val || '')} />

      {/* Controls */}
      <div className="flex items-center gap-3">
        <button
          onClick={handleRun}
          disabled={loading}
          className="flex items-center gap-2 bg-primary-600 hover:bg-primary-700 disabled:opacity-50 text-white px-4 py-2 rounded-lg text-sm font-medium transition-colors"
        >
          {loading ? <Loader2 size={16} className="animate-spin" /> : <Play size={16} />}
          {loading ? 'Running...' : 'Run Code'}
        </button>
        <button
          onClick={() => setCode(challenge.starterCode)}
          className="text-sm text-gray-400 hover:text-white transition-colors px-3 py-2"
        >
          Reset
        </button>
      </div>

      {/* Output */}
      {result && (
        <div className={`rounded-xl p-4 border ${
          result.allTestsPassed
            ? 'bg-green-500/5 border-green-500/20'
            : 'bg-red-500/5 border-red-500/20'
        }`}>
          <div className="flex items-center gap-2 mb-2">
            {result.allTestsPassed
              ? <CheckCircle2 size={18} className="text-green-400" />
              : <XCircle size={18} className="text-red-400" />
            }
            <span className={`text-sm font-medium ${result.allTestsPassed ? 'text-green-400' : 'text-red-400'}`}>
              {result.allTestsPassed ? 'All tests passed!' : 'Tests failed'}
            </span>
            {result.executionTimeMs != null && (
              <span className="text-xs text-gray-500 ml-auto">{result.executionTimeMs}ms</span>
            )}
          </div>

          {result.output && (
            <div className="mt-2">
              <p className="text-xs text-gray-500 mb-1">Output:</p>
              <pre className="font-mono text-sm text-gray-300 bg-surface-900 rounded-lg p-3 overflow-x-auto">
                {result.output}
              </pre>
            </div>
          )}

          {result.error && (
            <div className="mt-2">
              <p className="text-xs text-gray-500 mb-1">Error:</p>
              <pre className="font-mono text-sm text-red-400 bg-surface-900 rounded-lg p-3 overflow-x-auto">
                {result.error}
              </pre>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

