import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Plus, Minus, Eye } from 'lucide-react';

/**
 * Interactive Stack visualizer.
 * Users can push/pop values and see the internal state animate.
 */
export default function StackVisualizer() {
  const [stack, setStack] = useState([]);
  const [inputValue, setInputValue] = useState('');
  const [message, setMessage] = useState('Stack is empty. Push some values!');

  function handlePush() {
    const val = inputValue.trim() || `item-${stack.length + 1}`;
    setStack((prev) => [...prev, val]);
    setInputValue('');
    setMessage(`Pushed "${val}" onto the stack.`);
  }

  function handlePop() {
    if (stack.length === 0) {
      setMessage('Stack is empty — nothing to pop!');
      return;
    }
    const popped = stack[stack.length - 1];
    setStack((prev) => prev.slice(0, -1));
    setMessage(`Popped "${popped}" from the stack.`);
  }

  function handlePeek() {
    if (stack.length === 0) {
      setMessage('Stack is empty — nothing to peek!');
      return;
    }
    setMessage(`Top of stack: "${stack[stack.length - 1]}"`);
  }

  return (
    <div className="bg-surface-800 rounded-xl p-5">
      <h3 className="text-sm font-semibold text-gray-400 uppercase tracking-wide mb-4">
        Stack Visualizer
      </h3>

      {/* Controls */}
      <div className="flex items-center gap-2 mb-4">
        <input
          type="text"
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && handlePush()}
          placeholder="Value to push..."
          className="flex-1 bg-surface-900 text-white text-sm rounded-lg px-3 py-2 border border-surface-800 focus:border-primary-500 outline-none"
        />
        <button onClick={handlePush} className="p-2 bg-blue-600 hover:bg-blue-700 rounded-lg text-white" title="Push">
          <Plus size={16} />
        </button>
        <button onClick={handlePop} className="p-2 bg-red-600 hover:bg-red-700 rounded-lg text-white" title="Pop">
          <Minus size={16} />
        </button>
        <button onClick={handlePeek} className="p-2 bg-yellow-600 hover:bg-yellow-700 rounded-lg text-white" title="Peek">
          <Eye size={16} />
        </button>
      </div>

      {/* Status message */}
      <p className="text-xs text-gray-500 mb-3 font-mono">{message}</p>

      {/* Stack visualization */}
      <div className="flex flex-col-reverse items-center gap-1 min-h-[200px] bg-surface-900 rounded-lg p-4">
        <div className="w-48 h-1 bg-gray-700 rounded" /> {/* Stack base */}
        <AnimatePresence>
          {stack.map((item, i) => (
            <motion.div
              key={`${item}-${i}`}
              initial={{ opacity: 0, scale: 0.8, y: -20 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.8, y: -20 }}
              className={`w-48 px-3 py-2 rounded text-center text-sm font-mono border ${
                i === stack.length - 1
                  ? 'bg-primary-600/20 border-primary-500/50 text-primary-400'
                  : 'bg-surface-800 border-surface-800 text-gray-400'
              }`}
            >
              {item}
              {i === stack.length - 1 && (
                <span className="ml-2 text-xs text-primary-500">← top</span>
              )}
            </motion.div>
          ))}
        </AnimatePresence>

        {stack.length === 0 && (
          <p className="text-gray-600 text-sm italic">Empty stack</p>
        )}
      </div>

      <p className="text-xs text-gray-600 mt-2 text-right">Size: {stack.length}</p>
    </div>
  );
}

