        gradeBook.put(name, avg);
    }

    public static String topStudent() {
        String best = null;
        double bestAvg = -1;
        // TreeMap iterates alphabetically, so first-seen on a tie wins
        for (Map.Entry<String, Double> e : gradeBook.entrySet()) {
            if (e.getValue() > bestAvg) {
                bestAvg = e.getValue();
                best = e.getKey();
            }
        }
        return best;
    }

    public static void main(String[] args) {
        addStudent("Alice", List.of(90, 85, 92));
        addStudent("Bob",   List.of(88, 91, 87));
        addStudent("Carol", List.of(95, 80, 84));
        System.out.println("Grade Book: " + gradeBook);
        System.out.println("Top Student: " + topStudent());
    }
}


