    public static String transformAndJoin() {
        return words.stream().map(String::toUpperCase).collect(Collectors.joining(" | "));
    }

    public static Map<Integer, List<String>> groupByLength() {
        return words.stream().collect(Collectors.groupingBy(String::length));
    }

    public static void main(String[] args) {
        System.out.println("Count (len > 4): " + filterAndCount());
        System.out.println("Joined:          " + transformAndJoin());
        System.out.println("Grouped:         " + groupByLength());
