            "Alice,20,95\n" +
            "Bob,21,88\n" +
            "\n" +
            "Carol,19,92\n" +
            "BadLine\n";

    public static List<Map<String, String>> parseInput() throws IOException {
        List<Map<String, String>> records = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new StringReader(INPUT))) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.isBlank()) continue;
                String[] parts = line.split(",");
                if (parts.length != 3) continue;
                Map<String, String> record = new LinkedHashMap<>();
                record.put("name",  parts[0].trim());
                record.put("age",   parts[1].trim());
                record.put("score", parts[2].trim());
                records.add(record);
            }
        }
        return records;
    }

    public static void main(String[] args) throws IOException {
        parseInput().forEach(System.out::println);
    }
}


// ---------- Solution 5 ----------
class Solution5 {
    private final LinkedHashMap<Integer, String> map;

    public Solution5(int capacity) {
        // accessOrder = true means get() moves entry to end (most recent)
        this.map = new LinkedHashMap<>(capacity, 0.75f, true) {
            @Override
            protected boolean removeEldestEntry(Map.Entry<Integer, String> eldest) {
                return size() > capacity;
            }
        };
    }

    public String get(int key) {
        return map.getOrDefault(key, "-1");
    }

    public void put(int key, String value) {
        map.put(key, value);
    }

    public static void main(String[] args) {
        Solution5 cache = new Solution5(2);
        cache.put(1, "one");
        cache.put(2, "two");
        System.out.println(cache.get(1));   // "one"
        cache.put(3, "three");              // evicts 2
        System.out.println(cache.get(2));   // "-1"
        System.out.println(cache.get(3));   // "three"
    }
}


// ---------- Solution 6 ----------
class Solution6 {
    record Task(String name, int priority) {}

    public static List<String> scheduleTasks(List<Task> tasks) {
        PriorityQueue<Task> pq = new PriorityQueue<>(
            Comparator.comparingInt(Task::priority).thenComparing(Task::name)
        );
