class CommonPatterns {

    // ─────────────────────────────────────────────────────
    //  PATTERN 1: Frequency Counter
    // ─────────────────────────────────────────────────────
    Map<String, Integer> frequencyCounter(String[] words) {
        Map<String, Integer> freq = new HashMap<>();
        for (String word : words) {
            freq.merge(word, 1, Integer::sum);  // ← IDIOM!
            // Or: freq.put(word, freq.getOrDefault(word, 0) + 1);
        }
        return freq;
    }

    // ─────────────────────────────────────────────────────
    //  PATTERN 2: Group By (like SQL GROUP BY)
    // ─────────────────────────────────────────────────────
    Map<Integer, List<String>> groupByLength(List<String> words) {
        // Old way
        Map<Integer, List<String>> groups = new HashMap<>();
        for (String word : words) {
            groups.computeIfAbsent(word.length(), k -> new ArrayList<>())
                  .add(word);
        }

        // New way (Streams)
        return words.stream()
                    .collect(Collectors.groupingBy(String::length));
    }

    // ─────────────────────────────────────────────────────
    //  PATTERN 3: Two-Pointer with Set
    // ─────────────────────────────────────────────────────
    boolean hasDuplicate(int[] nums) {
        Set<Integer> seen = new HashSet<>();
        for (int num : nums) {
            if (!seen.add(num)) {  // add() returns false if already present!
                return true;
            }
        }
        return false;
    }

    // ─────────────────────────────────────────────────────
    //  PATTERN 4: Sliding Window with Deque
    // ─────────────────────────────────────────────────────
    int[] maxInWindow(int[] nums, int k) {
        Deque<Integer> deque = new ArrayDeque<>();  // stores indices
        List<Integer> result = new ArrayList<>();

        for (int i = 0; i < nums.length; i++) {
            // Remove indices outside window
            if (!deque.isEmpty() && deque.peekFirst() < i - k + 1) {
                deque.pollFirst();
            }
            // Remove smaller elements (they'll never be max)
            while (!deque.isEmpty() && nums[deque.peekLast()] < nums[i]) {
                deque.pollLast();
            }
            deque.offerLast(i);

            if (i >= k - 1) {
                result.add(nums[deque.peekFirst()]);
            }
        }
        return result.stream().mapToInt(Integer::intValue).toArray();
    }

    // ─────────────────────────────────────────────────────
    //  PATTERN 5: Top K Elements with Heap
    // ─────────────────────────────────────────────────────
    List<Integer> topKFrequent(int[] nums, int k) {
        // Step 1: Count frequencies
        Map<Integer, Integer> freq = new HashMap<>();
        for (int num : nums) {
            freq.merge(num, 1, Integer::sum);
        }

        // Step 2: Min-heap of size k (keeps k largest)
        PriorityQueue<Map.Entry<Integer, Integer>> heap = new PriorityQueue<>(
            Comparator.comparingInt(Map.Entry::getValue)
        );

        for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
            heap.offer(entry);
            if (heap.size() > k) {
                heap.poll();
            }
        }

        // Step 3: Extract results
        return heap.stream()
                   .map(Map.Entry::getKey)
                   .collect(Collectors.toList());
    }

    // ─────────────────────────────────────────────────────
    //  PATTERN 6: Graph Adjacency List
    // ─────────────────────────────────────────────────────
    Map<Integer, List<Integer>> buildGraph(int[][] edges) {
        Map<Integer, List<Integer>> graph = new HashMap<>();
        for (int[] edge : edges) {
            int from = edge[0], to = edge[1];
            graph.computeIfAbsent(from, k -> new ArrayList<>()).add(to);
            graph.computeIfAbsent(to, k -> new ArrayList<>()).add(from);  // undirected
        }
        return graph;
    }

    // ─────────────────────────────────────────────────────
    //  PATTERN 7: Remove Duplicates (preserve order)
    // ─────────────────────────────────────────────────────
    List<String> removeDuplicates(List<String> list) {
        return new ArrayList<>(new LinkedHashSet<>(list));
    }

    // ─────────────────────────────────────────────────────
    //  PATTERN 8: Sort with Custom Comparator
    // ─────────────────────────────────────────────────────
    void sortExamples(List<String> words) {
        // By length
        words.sort(Comparator.comparingInt(String::length));

        // By length, then alphabetically
        words.sort(Comparator.comparingInt(String::length)
                             .thenComparing(String::compareTo));

        // Reverse order
        words.sort(Comparator.reverseOrder());
    }

    // ─────────────────────────────────────────────────────
    //  PATTERN 9: Converting Between Collections
    // ─────────────────────────────────────────────────────
    void conversions() {
        List<String> list = Arrays.asList("a", "b", "c");

        // List → Set
        Set<String> set = new HashSet<>(list);

        // Set → List
        List<String> backToList = new ArrayList<>(set);

        // Array → List
        String[] array = {"x", "y", "z"};
        List<String> fromArray = Arrays.asList(array);  // Fixed-size!
        List<String> mutable = new ArrayList<>(Arrays.asList(array));

        // List → Array
        String[] toArray = list.toArray(new String[0]);

        // Stream → List
        List<String> filtered = list.stream()
                                    .filter(s -> s.length() > 1)
                                    .collect(Collectors.toList());
    }
}


