{"language": "java", "code": "// ============================================================
//  JAVA DATA STRUCTURES CHEAT SHEET
//  Quick reference for CS students
// ============================================================

/*
╔═══════════════════════════════════════════════════════════════════════════╗
║                         TABLE OF CONTENTS                                 ║
╠═══════════════════════════════════════════════════════════════════════════╣
║  1. OVERVIEW & HIERARCHY                                                  ║
║  2. LISTS (ArrayList, LinkedList)                                         ║
║  3. SETS (HashSet, TreeSet, LinkedHashSet)                                ║
║  4. MAPS (HashMap, TreeMap, LinkedHashMap)                                ║
║  5. QUEUES & DEQUES (PriorityQueue, ArrayDeque)                           ║
║  6. STACKS                                                                ║
║  7. TIME COMPLEXITY REFERENCE                                             ║
║  8. WHEN TO USE WHAT                                                      ║
║  9. COMMON PATTERNS & IDIOMS                                              ║
╚═══════════════════════════════════════════════════════════════════════════╝
*/

import java.util.*;
import java.util.stream.*;


// ============================================================
//  1. OVERVIEW & HIERARCHY
// ============================================================

/*
Collection Interface Hierarchy:

                    Iterable
                       |
                  Collection
                   /   |   \
                  /    |    \
              List   Set   Queue
               |      |      |
          ArrayList  HashSet  PriorityQueue
          LinkedList TreeSet  ArrayDeque
          Vector     LinkedHashSet

Map (separate hierarchy, not a Collection):
    Map
     |
  HashMap
  TreeMap
  LinkedHashMap
  Hashtable (legacy)

KEY CONCEPTS:
- List:  Ordered, allows duplicates, indexed access
- Set:   Unordered (usually), NO duplicates
- Queue: FIFO or priority-based ordering
- Map:   Key-value pairs, keys are unique
*/


// ============================================================
//  2. LISTS — Ordered collections with duplicates allowed
// ============================================================

class Lists {
    void arrayListDemo() {
        // ─────────────────────────────────────────────────────
        //  ArrayList — Resizable array, fast random access
        // ─────────────────────────────────────────────────────
        // USE WHEN: You need fast indexed access and mostly add to the end
        // AVOID WHEN: Lots of insertions/deletions in the middle

        List<String> list = new ArrayList<>();

        // Adding elements
        list.add("apple");              // O(1) amortized
        list.add("banana");
        list.add(0, "cherry");          // O(n) - shifts elements

        // Accessing elements
        String first = list.get(0);     // O(1) - fast!
        int size = list.size();         // O(1)

        // Searching
        boolean hasApple = list.contains("apple");  // O(n)
        int index = list.indexOf("banana");         // O(n)

        // Removing elements
        list.remove("apple");           // O(n) - searches then shifts
        list.remove(0);                 // O(n) - shifts elements
        list.clear();                   // O(n)

        // Iterating
        for (String item : list) {
            System.out.println(item);
        }

        // With streams
        list.stream()
            .filter(s -> s.startsWith("a"))
            .forEach(System.out::println);
    }

    void linkedListDemo() {
        // ─────────────────────────────────────────────────────
        //  LinkedList — Doubly-linked list, fast insertion/deletion
        // ─────────────────────────────────────────────────────
        // USE WHEN: Frequent insertions/deletions at both ends
        // AVOID WHEN: You need random access by index

        LinkedList<String> list = new LinkedList<>();

        // Adding elements
        list.add("middle");
        list.addFirst("first");         // O(1) - awesome!
        list.addLast("last");           // O(1)

        // Accessing elements
        String first = list.getFirst(); // O(1)
        String last = list.getLast();   // O(1)
        String byIndex = list.get(1);   // O(n) - slow! Has to traverse

        // Removing elements
        list.removeFirst();             // O(1)
        list.removeLast();              // O(1)

        // Queue operations (LinkedList implements Queue interface)
        list.offer("item");             // add to end
        String head = list.poll();      // remove from front
        String peek = list.peek();      // look at front without removing
    }
}


// ============================================================
//  3. SETS — No duplicates allowed
// ============================================================

class Sets {
    void hashSetDemo() {
        // ─────────────────────────────────────────────────────
        //  HashSet — Unordered, fast operations
        // ─────────────────────────────────────────────────────
        // USE WHEN: You need to check "is X in the set?" quickly
        // AVOID WHEN: You need ordering

        Set<String> set = new HashSet<>();

        // Adding elements
        set.add("apple");               // O(1) average
        set.add("banana");
        set.add("apple");               // Duplicate! Won't be added
        // set now has: {apple, banana} (order not guaranteed!)

        // Checking membership
        boolean has = set.contains("apple");    // O(1) average - FAST!

        // Removing
        set.remove("apple");            // O(1) average

        // Size
        int size = set.size();          // O(1)

        // Set operations
        Set<String> set2 = new HashSet<>(Arrays.asList("banana", "cherry"));

        // Union
        Set<String> union = new HashSet<>(set);
        union.addAll(set2);             // {apple, banana, cherry}

        // Intersection
        Set<String> intersection = new HashSet<>(set);
        intersection.retainAll(set2);   // {banana}

        // Difference
        Set<String> diff = new HashSet<>(set);
        diff.removeAll(set2);           // {apple}
    }

    void treeSetDemo() {
        // ─────────────────────────────────────────────────────
        //  TreeSet — Sorted order (Red-Black tree)
        // ─────────────────────────────────────────────────────
        // USE WHEN: You need sorted elements
        // AVOID WHEN: You don't care about order (HashSet is faster)

        Set<Integer> set = new TreeSet<>();
        set.add(5);
        set.add(1);
        set.add(3);
        // Iteration order: 1, 3, 5 (automatically sorted!)

        // Operations are O(log n)
        set.add(7);                     // O(log n)
        set.contains(3);                // O(log n)
        set.remove(5);                  // O(log n)

        // TreeSet-specific operations
        TreeSet<Integer> treeSet = new TreeSet<>(set);
        Integer first = treeSet.first();        // smallest element
        Integer last = treeSet.last();          // largest element
        Integer floor = treeSet.floor(4);       // largest ≤ 4
        Integer ceiling = treeSet.ceiling(4);   // smallest ≥ 4
    }

    void linkedHashSetDemo() {
        // ─────────────────────────────────────────────────────
        //  LinkedHashSet — Maintains insertion order
        // ─────────────────────────────────────────────────────
        // USE WHEN: You want HashSet speed but need predictable iteration order

        Set<String> set = new LinkedHashSet<>();
        set.add("apple");
        set.add("banana");
        set.add("cherry");
        // Iteration order: apple, banana, cherry (insertion order preserved!)

        // Same O(1) operations as HashSet, with slight overhead for ordering
    }
}


// ============================================================
//  4. MAPS — Key-Value pairs
// ============================================================

class Maps {
    void hashMapDemo() {
        // ─────────────────────────────────────────────────────
        //  HashMap — Unordered key-value pairs, fast lookup
        // ─────────────────────────────────────────────────────
        // USE WHEN: You need to associate values with keys
        // AVOID WHEN: You need keys in sorted order

        Map<String, Integer> map = new HashMap<>();

        // Adding/updating
        map.put("apple", 5);            // O(1) average
        map.put("banana", 3);
        map.put("apple", 10);           // Updates existing key

        // Getting values
        Integer val = map.get("apple");         // O(1) average → 10
        Integer def = map.getOrDefault("cherry", 0);  // O(1) → 0 (default)

        // Checking existence
        boolean hasKey = map.containsKey("apple");      // O(1) average
        boolean hasVal = map.containsValue(10);         // O(n) - slow!

        // Removing
        map.remove("banana");           // O(1) average

        // Useful update patterns
        map.putIfAbsent("date", 1);     // Only put if key doesn't exist

        // merge: perfect for counting!
        map.merge("apple", 1, Integer::sum);    // add 1 to existing value

        // compute: update based on current value
        map.compute("apple", (k, v) -> v == null ? 1 : v + 1);

        // Iterating
        for (Map.Entry<String, Integer> entry : map.entrySet()) {
            System.out.println(entry.getKey() + ": " + entry.getValue());
        }

        // Or with streams
        map.forEach((key, value) -> System.out.println(key + ": " + value));

        // Getting keys/values
        Set<String> keys = map.keySet();            // View of keys
        Collection<Integer> values = map.values();  // View of values
    }

    void treeMapDemo() {
        // ─────────────────────────────────────────────────────
        //  TreeMap — Sorted by keys (Red-Black tree)
        // ─────────────────────────────────────────────────────
        // USE WHEN: You need keys in sorted order

        Map<String, Integer> map = new TreeMap<>();
        map.put("banana", 2);
        map.put("apple", 1);
        map.put("cherry", 3);
        // Iteration order: apple, banana, cherry (sorted by key!)

        // All operations O(log n)
        map.put("date", 4);             // O(log n)
        map.get("apple");               // O(log n)

        // TreeMap-specific operations
        TreeMap<String, Integer> treeMap = new TreeMap<>(map);
        String firstKey = treeMap.firstKey();       // smallest key
        String lastKey = treeMap.lastKey();         // largest key
        Map.Entry<String, Integer> firstEntry = treeMap.firstEntry();
    }

    void linkedHashMapDemo() {
        // ─────────────────────────────────────────────────────
        //  LinkedHashMap — Maintains insertion order (or access order!)
        // ─────────────────────────────────────────────────────
        // USE WHEN: You want HashMap speed with predictable iteration

        Map<String, Integer> map = new LinkedHashMap<>();
        map.put("apple", 1);
        map.put("banana", 2);
        // Iteration order: apple, banana (insertion order)

        // LRU Cache trick: access-order mode
        Map<String, Integer> lruCache = new LinkedHashMap<>(16, 0.75f, true) {
            @Override
            protected boolean removeEldestEntry(Map.Entry<String, Integer> eldest) {
                return size() > 5;  // Keep only 5 most recently accessed
            }
        };
    }
}


// ============================================================
//  5. QUEUES & DEQUES — FIFO and priority-based
// ============================================================

class QueuesAndDeques {
    void priorityQueueDemo() {
        // ─────────────────────────────────────────────────────
        //  PriorityQueue — Min-heap by default
        // ─────────────────────────────────────────────────────
        // USE WHEN: You need to repeatedly get the smallest (or largest) element

        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        minHeap.offer(5);               // O(log n)
        minHeap.offer(1);
        minHeap.offer(3);

        System.out.println(minHeap.peek());  // 1 (smallest, doesn't remove)
        System.out.println(minHeap.poll());  // 1 (removes smallest)
        System.out.println(minHeap.poll());  // 3 (next smallest)

        // Max-heap: reverse the comparator
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        maxHeap.offer(5);
        maxHeap.offer(1);
        maxHeap.offer(3);
        System.out.println(maxHeap.poll());  // 5 (largest)

        // Custom comparator
        PriorityQueue<String> byLength = new PriorityQueue<>(
            Comparator.comparingInt(String::length)
        );

        // Common use case: top K elements
        PriorityQueue<Integer> topK = new PriorityQueue<>(3);  // keep 3 largest
        for (int num : Arrays.asList(1, 5, 3, 9, 2, 8, 4)) {
            topK.offer(num);
            if (topK.size() > 3) {
                topK.poll();  // Remove smallest
            }
        }
        // topK now has: 5, 8, 9
    }

    void arrayDequeDemo() {
        // ─────────────────────────────────────────────────────
        //  ArrayDeque — Double-ended queue, use this for stacks/queues!
        // ─────────────────────────────────────────────────────
        // USE WHEN: You need a stack or queue (faster than LinkedList!)

        Deque<String> deque = new ArrayDeque<>();

        // As a QUEUE (FIFO)
        deque.offer("first");           // Add to end
        deque.offer("second");
        String head = deque.poll();     // Remove from front → "first"

        // As a STACK (LIFO)
        deque.push("bottom");           // Add to front
        deque.push("top");
        String top = deque.pop();       // Remove from front → "top"

        // Double-ended operations
        deque.addFirst("front");        // O(1)
        deque.addLast("back");          // O(1)
        deque.removeFirst();            // O(1)
        deque.removeLast();             // O(1)

        // Peeking
        String first = deque.peekFirst();   // Look at front
        String last = deque.peekLast();     // Look at back
    }
}


// ============================================================
//  6. STACKS — LIFO (Last In, First Out)
// ============================================================

class Stacks {
    void stackDemo() {
        // ─────────────────────────────────────────────────────
        //  Stack — Legacy class, use ArrayDeque instead!
        // ─────────────────────────────────────────────────────
        // NOTE: Stack extends Vector (synchronized, slow)
        //       Prefer ArrayDeque for stack operations

        Stack<String> stack = new Stack<>();
        stack.push("first");            // Add to top
        stack.push("second");
        String top = stack.pop();       // Remove from top → "second"
        String peek = stack.peek();     // Look at top → "first"
        boolean empty = stack.isEmpty();

        // Better: use ArrayDeque as a stack
        Deque<String> betterStack = new ArrayDeque<>();
        betterStack.push("item");
        String item = betterStack.pop();
    }
}


// ============================================================
//  7. TIME COMPLEXITY REFERENCE
// ============================================================

/*
╔═══════════════════════════════════════════════════════════════════════════╗
║                    TIME COMPLEXITY CHEAT SHEET                            ║
╠═══════════════════════════════════════════════════════════════════════════╣
║  Data Structure      │ Add      │ Remove   │ Get      │ Contains │ Notes  ║
╠═══════════════════════════════════════════════════════════════════════════╣
║  ArrayList           │ O(1)*    │ O(n)     │ O(1)     │ O(n)     │ *amort ║
║  LinkedList          │ O(1)     │ O(1)**   │ O(n)     │ O(n)     │ **ends ║
║  HashSet             │ O(1)     │ O(1)     │ N/A      │ O(1)     │ avg    ║
║  TreeSet             │ O(log n) │ O(log n) │ N/A      │ O(log n) │        ║
║  HashMap             │ O(1)     │ O(1)     │ O(1)     │ O(1)     │ avg    ║
║  TreeMap             │ O(log n) │ O(log n) │ O(log n) │ O(log n) │        ║
║  PriorityQueue       │ O(log n) │ O(log n) │ O(1)**   │ O(n)     │ **peek ║
║  ArrayDeque          │ O(1)     │ O(1)     │ N/A      │ N/A      │ ends   ║
╚═══════════════════════════════════════════════════════════════════════════╝

KEY:
  O(1)     = constant time (instant, doesn't depend on size)
  O(log n) = logarithmic (halves the problem each step, like binary search)
  O(n)     = linear (proportional to size, like scanning a list)
  O(n²)    = quadratic (nested loops, avoid if possible!)

  *amortized  = O(1) on average, occasionally O(n) when resizing
  avg         = O(1) average case, O(n) worst case (rare hash collisions)
*/


// ============================================================
//  8. WHEN TO USE WHAT — Decision Tree
// ============================================================

/*
┌─────────────────────────────────────────────────────────────┐
│  NEED TO STORE A SINGLE TYPE OF ELEMENT?                    │
└─────────────────────────────────────────────────────────────┘
           │
           ├─→ Duplicates allowed? → YES → LIST
           │         │
           │         ├─→ Need fast random access? → ArrayList
           │         └─→ Lots of add/remove at ends? → LinkedList
           │
           └─→ No duplicates? → SET
                     │
                     ├─→ Need sorted order? → TreeSet
                     ├─→ Need insertion order? → LinkedHashSet
                     └─→ Don't care about order? → HashSet

┌─────────────────────────────────────────────────────────────┐
│  NEED KEY-VALUE PAIRS?                                       │
└─────────────────────────────────────────────────────────────┘
           │
           ├─→ Need keys sorted? → TreeMap
           ├─→ Need insertion order? → LinkedHashMap
           └─→ Don't care about order? → HashMap

┌─────────────────────────────────────────────────────────────┐
│  NEED SPECIAL ORDERING?                                      │
└─────────────────────────────────────────────────────────────┘
           │
           ├─→ First in, first out (FIFO)? → ArrayDeque (as queue)
           ├─→ Last in, first out (LIFO)? → ArrayDeque (as stack)
           └─→ Always need smallest/largest? → PriorityQueue

┌─────────────────────────────────────────────────────────────┐
│  REAL-WORLD USE CASES                                        │
└─────────────────────────────────────────────────────────────┘

HashMap:
  • Word frequency counter
  • Caching results
  • Adjacency list for graphs
  • Memoization in dynamic programming

ArrayList:
  • Resizable array
  • Building a result list
  • Random access needed

HashSet:
  • Remove duplicates from a list
  • Check if element exists (fast!)
  • Set operations (union, intersection)

PriorityQueue:
  • Dijkstra's algorithm
  • Top K elements
  • Merge K sorted lists
  • Event scheduling

TreeMap/TreeSet:
  • Range queries
  • Finding floor/ceiling values
  • Maintaining sorted data

ArrayDeque:
  • BFS (queue)
  • DFS (stack)
  • Sliding window problems
  • Undo/redo functionality
*/


// ============================================================
//  9. COMMON PATTERNS & IDIOMS
// ============================================================

class CommonPatterns {

    // ─────────────────────────────────────────────────────
    //  PATTERN 1: Frequency Counter
    // ─────────────────────────────────────────────────────
    Map<String, Integer> frequencyCounter(String[] words) {
        Map<String, Integer> freq = new HashMap<>();
        for (String word : words) {
            freq.merge(word, 1, Integer::sum);  // ← IDIOM!
            // Or: freq.put(word, freq.getOrDefault(word, 0) + 1);
        }
        return freq;
    }

    // ─────────────────────────────────────────────────────
    //  PATTERN 2: Group By (like SQL GROUP BY)
    // ─────────────────────────────────────────────────────
    Map<Integer, List<String>> groupByLength(List<String> words) {
        // Old way
        Map<Integer, List<String>> groups = new HashMap<>();
        for (String word : words) {
            groups.computeIfAbsent(word.length(), k -> new ArrayList<>())
                  .add(word);
        }

        // New way (Streams)
        return words.stream()
                    .collect(Collectors.groupingBy(String::length));
    }

    // ─────────────────────────────────────────────────────
    //  PATTERN 3: Two-Pointer with Set
    // ─────────────────────────────────────────────────────
    boolean hasDuplicate(int[] nums) {
        Set<Integer> seen = new HashSet<>();
        for (int num : nums) {
            if (!seen.add(num)) {  // add() returns false if already present!
                return true;
            }
        }
        return false;
    }

    // ─────────────────────────────────────────────────────
    //  PATTERN 4: Sliding Window with Deque
    // ─────────────────────────────────────────────────────
    int[] maxInWindow(int[] nums, int k) {
        Deque<Integer> deque = new ArrayDeque<>();  // stores indices
        List<Integer> result = new ArrayList<>();

        for (int i = 0; i < nums.length; i++) {
            // Remove indices outside window
            if (!deque.isEmpty() && deque.peekFirst() < i - k + 1) {
                deque.pollFirst();
            }
            // Remove smaller elements (they'll never be max)
            while (!deque.isEmpty() && nums[deque.peekLast()] < nums[i]) {
                deque.pollLast();
            }
            deque.offerLast(i);

            if (i >= k - 1) {
                result.add(nums[deque.peekFirst()]);
            }
        }
        return result.stream().mapToInt(Integer::intValue).toArray();
    }

    // ─────────────────────────────────────────────────────
    //  PATTERN 5: Top K Elements with Heap
    // ─────────────────────────────────────────────────────
    List<Integer> topKFrequent(int[] nums, int k) {
        // Step 1: Count frequencies
        Map<Integer, Integer> freq = new HashMap<>();
        for (int num : nums) {
            freq.merge(num, 1, Integer::sum);
        }

        // Step 2: Min-heap of size k (keeps k largest)
        PriorityQueue<Map.Entry<Integer, Integer>> heap = new PriorityQueue<>(
            Comparator.comparingInt(Map.Entry::getValue)
        );

        for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
            heap.offer(entry);
            if (heap.size() > k) {
                heap.poll();
            }
        }

        // Step 3: Extract results
        return heap.stream()
                   .map(Map.Entry::getKey)
                   .collect(Collectors.toList());
    }

    // ─────────────────────────────────────────────────────
    //  PATTERN 6: Graph Adjacency List
    // ─────────────────────────────────────────────────────
    Map<Integer, List<Integer>> buildGraph(int[][] edges) {
        Map<Integer, List<Integer>> graph = new HashMap<>();
        for (int[] edge : edges) {
            int from = edge[0], to = edge[1];
            graph.computeIfAbsent(from, k -> new ArrayList<>()).add(to);
            graph.computeIfAbsent(to, k -> new ArrayList<>()).add(from);  // undirected
        }
        return graph;
    }

    // ─────────────────────────────────────────────────────
    //  PATTERN 7: Remove Duplicates (preserve order)
    // ─────────────────────────────────────────────────────
    List<String> removeDuplicates(List<String> list) {
        return new ArrayList<>(new LinkedHashSet<>(list));
    }

    // ─────────────────────────────────────────────────────
    //  PATTERN 8: Sort with Custom Comparator
    // ─────────────────────────────────────────────────────
    void sortExamples(List<String> words) {
        // By length
        words.sort(Comparator.comparingInt(String::length));

        // By length, then alphabetically
        words.sort(Comparator.comparingInt(String::length)
                             .thenComparing(String::compareTo));

        // Reverse order
        words.sort(Comparator.reverseOrder());
    }

    // ─────────────────────────────────────────────────────
    //  PATTERN 9: Converting Between Collections
    // ─────────────────────────────────────────────────────
    void conversions() {
        List<String> list = Arrays.asList("a", "b", "c");

        // List → Set
        Set<String> set = new HashSet<>(list);

        // Set → List
        List<String> backToList = new ArrayList<>(set);

        // Array → List
        String[] array = {"x", "y", "z"};
        List<String> fromArray = Arrays.asList(array);  // Fixed-size!
        List<String> mutable = new ArrayList<>(Arrays.asList(array));

        // List → Array
        String[] toArray = list.toArray(new String[0]);

        // Stream → List
        List<String> filtered = list.stream()
                                    .filter(s -> s.length() > 1)
                                    .collect(Collectors.toList());
    }
}


// ============================================================
//  QUICK REFERENCE: Which method does what?
// ============================================================

/*
╔═══════════════════════════════════════════════════════════════════════════╗
║                         MAP METHOD QUICK REF                              ║
╠═══════════════════════════════════════════════════════════════════════════╣
║  put(k, v)              │ Insert or replace                               ║
║  get(k)                 │ Retrieve value (or null)                        ║
║  getOrDefault(k, def)   │ Retrieve value (or default if absent)           ║
║  containsKey(k)         │ Check if key exists                             ║
║  putIfAbsent(k, v)      │ Insert only if key doesn't exist                ║
║  merge(k, v, fn)        │ Insert or combine with existing (COUNTING!)     ║
║  compute(k, fn)         │ Update value based on key and old value         ║
║  computeIfAbsent(k, fn) │ Insert computed value if key absent (GROUPING!) ║
╚═══════════════════════════════════════════════════════════════════════════╝

╔═══════════════════════════════════════════════════════════════════════════╗
║                       QUEUE/DEQUE METHOD QUICK REF                        ║
╠═══════════════════════════════════════════════════════════════════════════╣
║  offer() / add()        │ Add to end (queue) or front (stack)             ║
║  poll() / remove()      │ Remove from front (queue) or front (stack)      ║
║  peek() / element()     │ Look at front without removing                  ║
║  push() / pop()         │ Stack operations (addFirst/removeFirst)         ║
╚═══════════════════════════════════════════════════════════════════════════╝
*/


// ============================================================
//  FINAL TIPS
// ============================================================

/*
1. DEFAULT TO HashMap/HashSet — they're O(1) and almost always what you want

2. USE TreeMap/TreeSet ONLY IF:
   - You need sorted keys/elements
   - You need range queries (floor, ceiling, subMap, etc.)

3. ArrayList vs LinkedList:
   - 95% of the time: ArrayList
   - Only use LinkedList if you're doing lots of addFirst/removeLast

4. NEVER USE:
   - Vector (use ArrayList)
   - Hashtable (use HashMap)
   - Stack (use ArrayDeque)

5. REMEMBER:
   - Set.add() returns false if element already exists (useful for duplicates!)
   - Map.merge() is perfect for counting
   - Map.computeIfAbsent() is perfect for grouping
   - Streams make transformations clean (but learn loops first!)

6. LEETCODE TIP:
   - Two Sum → HashMap
   - Valid Parentheses → Stack
   - Top K Elements → PriorityQueue
   - Sliding Window Maximum → Deque
*/
