import React, { useState, useRef, useEffect } from 'react';
import { ChevronDown, ArrowRight, Code, Loader2 } from 'lucide-react';

const CodeVerter = () => {
  // Top 25 programming languages
  const languages = [
    'Python', 'JavaScript', 'TypeScript', 'Java', 'C++', 'C#', 'C', 'Go', 
    'Rust', 'Swift', 'Kotlin', 'PHP', 'Ruby', 'Scala', 'R', 'MATLAB', 
    'Perl', 'Haskell', 'Lua', 'Dart', 'Elixir', 'F#', 'Clojure', 
    'Objective-C', 'Visual Basic'
  ];

  const [sourceCode, setSourceCode] = useState('# Example Python code\ndef fibonacci(n):\n    if n <= 1:\n        return n\n    return fibonacci(n-1) + fibonacci(n-2)\n\nprint(fibonacci(10))');
  const [targetCode, setTargetCode] = useState('');
  const [sourceLanguage, setSourceLanguage] = useState('Python');
  const [targetLanguage, setTargetLanguage] = useState('JavaScript');
  const [isConverting, setIsConverting] = useState(false);
  const [error, setError] = useState('');

  const convertCode = async () => {
    if (!sourceCode.trim()) {
      setError('Please enter some code to convert');
      return;
    }

    setIsConverting(true);
    setError('');
    setTargetCode('');

    try {
      const prompt = `Convert the following ${sourceLanguage} code to ${targetLanguage}. Only return the converted code without any explanation or markdown formatting:

${sourceCode}`;

      const response = await window.claude.complete(prompt);
      setTargetCode(response);
    } catch (err) {
      setError('Failed to convert code. Please try again.');
      console.error('Conversion error:', err);
    } finally {
      setIsConverting(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-900 text-white">
      {/* Header */}
      <div className="bg-gray-800 border-b border-gray-700 px-6 py-4">
        <div className="flex items-center gap-3">
          <Code className="w-8 h-8 text-blue-400" />
          <h1 className="text-2xl font-bold text-white">CodeVerter</h1>
          <span className="text-gray-400 text-sm ml-2">Programming Language Converter</span>
        </div>
      </div>

      {/* Main Content */}
      <div className="p-6">
        <div className="max-w-7xl mx-auto">
          {/* Language Selection */}
          <div className="flex items-center justify-center gap-4 mb-6">
            <LanguageDropdown 
              value={sourceLanguage}
              onChange={setSourceLanguage}
              languages={languages}
              placeholder="Source Language"
            />
            <ArrowRight className="w-6 h-6 text-gray-400" />
            <LanguageDropdown 
              value={targetLanguage}
              onChange={setTargetLanguage}
              languages={languages}
              placeholder="Target Language"
            />
          </div>

          {/* Convert Button */}
          <div className="flex justify-center mb-6">
            <button
              onClick={convertCode}
              disabled={isConverting}
              className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 disabled:bg-blue-800 disabled:cursor-not-allowed px-6 py-3 rounded-lg font-medium transition-colors"
            >
              {isConverting ? (
                <>
                  <Loader2 className="w-5 h-5 animate-spin" />
                  Converting...
                </>
              ) : (
                <>
                  <Code className="w-5 h-5" />
                  Convert Code
                </>
              )}
            </button>
          </div>

          {/* Error Message */}
          {error && (
            <div className="bg-red-900 border border-red-700 text-red-200 px-4 py-3 rounded-lg mb-6 text-center">
              {error}
            </div>
          )}

          {/* Code Panels */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {/* Source Code Panel */}
            <div className="bg-gray-800 rounded-lg overflow-hidden">
              <div className="bg-gray-700 px-4 py-3 border-b border-gray-600">
                <h3 className="font-medium text-gray-200">Source Code ({sourceLanguage})</h3>
              </div>
              <textarea
                value={sourceCode}
                onChange={(e) => setSourceCode(e.target.value)}
                className="w-full h-96 p-4 bg-gray-800 text-gray-100 font-mono text-sm resize-none border-none outline-none"
                placeholder="Enter your source code here..."
              />
            </div>

            {/* Target Code Panel */}
            <div className="bg-gray-800 rounded-lg overflow-hidden">
              <div className="bg-gray-700 px-4 py-3 border-b border-gray-600">
                <h3 className="font-medium text-gray-200">Converted Code ({targetLanguage})</h3>
              </div>
              <div className="relative">
                <textarea
                  value={targetCode}
                  readOnly
                  className="w-full h-96 p-4 bg-gray-800 text-gray-100 font-mono text-sm resize-none border-none outline-none"
                  placeholder={isConverting ? "Converting..." : "Converted code will appear here..."}
                />
                {isConverting && (
                  <div className="absolute inset-0 bg-gray-800 bg-opacity-75 flex items-center justify-center">
                    <Loader2 className="w-8 h-8 animate-spin text-blue-400" />
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* Footer */}
          <div className="mt-8 text-center text-gray-400 text-sm">
            <p>CodeVerter uses Claude AI to convert code between programming languages.</p>
            <p className="mt-1">Results may require manual review and adjustment.</p>
          </div>
        </div>
      </div>
    </div>
  );
};

// Custom Language Dropdown Component
const LanguageDropdown = ({ value, onChange, languages, placeholder }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const dropdownRef = useRef(null);

  const filteredLanguages = languages.filter(lang =>
    lang.toLowerCase().includes(searchTerm.toLowerCase())
  );

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setIsOpen(false);
        setSearchTerm('');
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleLanguageSelect = (language) => {
    onChange(language);
    setIsOpen(false);
    setSearchTerm('');
  };

  return (
    <div className="relative" ref={dropdownRef}>
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="flex items-center justify-between gap-2 bg-gray-700 hover:bg-gray-600 px-4 py-3 rounded-lg min-w-48 text-left border border-gray-600"
      >
        <span className="text-gray-200">{value || placeholder}</span>
        <ChevronDown className={`w-5 h-5 text-gray-400 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
      </button>

      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-1 bg-gray-700 border border-gray-600 rounded-lg shadow-lg z-50 max-h-64 overflow-hidden">
          <div className="p-2 border-b border-gray-600">
            <input
              type="text"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              placeholder="Search languages..."
              className="w-full px-3 py-2 bg-gray-800 text-gray-200 rounded border border-gray-600 text-sm outline-none focus:border-blue-500"
              autoFocus
            />
          </div>
          <div className="max-h-48 overflow-y-auto">
            {filteredLanguages.length > 0 ? (
              filteredLanguages.map((language) => (
                <button
                  key={language}
                  onClick={() => handleLanguageSelect(language)}
                  className={`w-full text-left px-4 py-2 hover:bg-gray-600 transition-colors ${
                    value === language ? 'bg-blue-600 text-white' : 'text-gray-200'
                  }`}
                >
                  {language}
                </button>
              ))
            ) : (
              <div className="px-4 py-2 text-gray-400 text-sm">No languages found</div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default CodeVerter;

