import React, { useState, useRef, useEffect } from 'react';
import { ChevronDown, ArrowRight, Terminal, Loader2 } from 'lucide-react';

const languages = [
  'Python', 'JavaScript', 'TypeScript', 'Java', 'C++', 'C#', 'C', 'Go',
  'Rust', 'Swift', 'Kotlin', 'PHP', 'Ruby', 'Scala', 'R', 'MATLAB',
  'Perl', 'Haskell', 'Lua', 'Dart', 'Elixir', 'F#', 'Clojure',
  'Objective-C', 'Visual Basic'
];

const LanguageDropdown = ({ value, onChange }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState('');
  const ref = useRef(null);

  const filtered = languages.filter(l => l.toLowerCase().includes(search.toLowerCase()));

  useEffect(() => {
    const handler = e => { if (ref.current && !ref.current.contains(e.target)) { setIsOpen(false); setSearch(''); } };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  return (
    <div className="relative" ref={ref}>
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="flex items-center gap-2 px-3 py-1.5 border border-green-500 text-green-400 font-mono text-sm hover:bg-green-500 hover:text-black transition-colors min-w-40"
      >
        <span className="flex-1 text-left">{value}</span>
        <ChevronDown className={`w-3 h-3 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
      </button>
      {isOpen && (
        <div className="absolute top-full left-0 mt-0.5 bg-black border border-green-500 z-50 w-48 shadow-lg shadow-green-900/40">
          <input
            autoFocus
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="> search..."
            className="w-full px-3 py-1.5 bg-black text-green-400 font-mono text-xs border-b border-green-800 outline-none placeholder-green-900"
          />
          <div className="max-h-48 overflow-y-auto">
            {filtered.map(l => (
              <button
                key={l}
                onClick={() => { onChange(l); setIsOpen(false); setSearch(''); }}
                className={`w-full text-left px-3 py-1.5 font-mono text-xs hover:bg-green-500 hover:text-black transition-colors ${value === l ? 'text-black bg-green-500' : 'text-green-400'}`}
              >
                {value === l ? '> ' : '  '}{l}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default function CodeVerter() {
  const [sourceCode, setSourceCode] = useState('# Example Python code\ndef fibonacci(n):\n    if n <= 1:\n        return n\n    return fibonacci(n-1) + fibonacci(n-2)\n\nprint(fibonacci(10))');
  const [targetCode, setTargetCode] = useState('');
  const [sourceLang, setSourceLang] = useState('Python');
  const [targetLang, setTargetLang] = useState('JavaScript');
  const [isConverting, setIsConverting] = useState(false);
  const [error, setError] = useState('');
  const [dots, setDots] = useState('');

  useEffect(() => {
    if (!isConverting) return;
    const id = setInterval(() => setDots(d => d.length >= 3 ? '' : d + '.'), 400);
    return () => clearInterval(id);
  }, [isConverting]);

  const convert = async () => {
    if (!sourceCode.trim()) { setError('ERR: no input detected'); return; }
    setIsConverting(true); setError(''); setTargetCode('');
    try {
      const res = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model: 'claude-sonnet-4-20250514',
          max_tokens: 1000,
          messages: [{
            role: 'user',
            content: `Convert the following ${sourceLang} code to ${targetLang}. Return only the converted code, no explanation or markdown fences:\n\n${sourceCode}`
          }]
        })
      });
      const data = await res.json();
      setTargetCode(data.content?.[0]?.text || '');
    } catch {
      setError('ERR: conversion failed — check connection and retry');
    } finally {
      setIsConverting(false);
    }
  };

  return (
    <div className="min-h-screen bg-black text-green-400 font-mono flex flex-col" style={{ fontFamily: "'Courier New', monospace" }}>
      {/* Scanline overlay */}
      <div className="pointer-events-none fixed inset-0 z-10" style={{
        backgroundImage: 'repeating-linear-gradient(0deg, transparent, transparent 2px, rgba(0,0,0,0.08) 2px, rgba(0,0,0,0.08) 4px)',
      }} />

      {/* Header */}
      <div className="border-b border-green-800 px-6 py-3 flex items-center gap-3">
        <Terminal className="w-5 h-5 text-green-500" />
        <span className="text-green-500 text-lg font-bold tracking-widest">CODEVERTER</span>
        <span className="text-green-800 text-xs ml-2">v1.0.0 // AI-POWERED TRANSPILER</span>
        <div className="ml-auto flex gap-1.5">
          {['#f87171','#fbbf24','#4ade80'].map((c, i) => (
            <div key={i} className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: c, opacity: 0.7 }} />
          ))}
        </div>
      </div>

      {/* Toolbar */}
      <div className="border-b border-green-900 px-6 py-3 flex items-center gap-4 bg-black">
        <span className="text-green-800 text-xs">SOURCE</span>
        <LanguageDropdown value={sourceLang} onChange={setSourceLang} />
        <ArrowRight className="w-4 h-4 text-green-700" />
        <span className="text-green-800 text-xs">TARGET</span>
        <LanguageDropdown value={targetLang} onChange={setTargetLang} />
        <div className="ml-auto">
          <button
            onClick={convert}
            disabled={isConverting}
            className="flex items-center gap-2 px-4 py-1.5 border border-green-500 text-green-400 text-sm hover:bg-green-500 hover:text-black transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isConverting
              ? <><Loader2 className="w-3 h-3 animate-spin" />CONVERTING{dots}</>
              : <>{'>'} RUN CONVERT</>}
          </button>
        </div>
      </div>

      {/* Error bar */}
      {error && (
        <div className="px-6 py-2 bg-red-950 border-b border-red-800 text-red-400 text-xs">
          {error}
        </div>
      )}

      {/* Editor panes */}
      <div className="flex flex-1 overflow-hidden" style={{ minHeight: '500px' }}>
        {/* Source */}
        <div className="flex flex-col flex-1 border-r border-green-900">
          <div className="px-4 py-1.5 bg-green-950/30 border-b border-green-900 flex items-center gap-2">
            <span className="text-green-700 text-xs">01</span>
            <span className="text-green-600 text-xs">//</span>
            <span className="text-green-500 text-xs">{sourceLang.toUpperCase()} INPUT</span>
            <span className="ml-auto text-green-800 text-xs">{sourceCode.split('\n').length} lines</span>
          </div>
          <textarea
            value={sourceCode}
            onChange={e => setSourceCode(e.target.value)}
            spellCheck={false}
            className="flex-1 p-4 bg-black text-green-300 text-sm resize-none outline-none leading-relaxed"
            style={{ fontFamily: "'Courier New', monospace", caretColor: '#4ade80' }}
            placeholder="> paste source code here..."
          />
        </div>

        {/* Target */}
        <div className="flex flex-col flex-1">
          <div className="px-4 py-1.5 bg-green-950/30 border-b border-green-900 flex items-center gap-2">
            <span className="text-green-700 text-xs">02</span>
            <span className="text-green-600 text-xs">//</span>
            <span className="text-green-500 text-xs">{targetLang.toUpperCase()} OUTPUT</span>
            {targetCode && <span className="ml-auto text-green-800 text-xs">{targetCode.split('\n').length} lines</span>}
          </div>
          <div className="relative flex-1">
            <textarea
              readOnly
              value={targetCode}
              spellCheck={false}
              className="absolute inset-0 w-full h-full p-4 bg-black text-green-300 text-sm resize-none outline-none leading-relaxed"
              style={{ fontFamily: "'Courier New', monospace" }}
              placeholder={isConverting ? `> processing${dots}` : '> awaiting conversion...'}
            />
            {isConverting && (
              <div className="absolute inset-0 bg-black/60 flex flex-col items-center justify-center gap-2">
                <Loader2 className="w-6 h-6 animate-spin text-green-500" />
                <span className="text-green-500 text-xs animate-pulse">TRANSPILING{dots}</span>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Status bar */}
      <div className="border-t border-green-900 px-6 py-1.5 flex items-center gap-4 text-green-800 text-xs">
        <span className="text-green-600">●</span>
        <span>READY</span>
        <span className="ml-auto">CODEVERTER // POWERED BY CLAUDE AI</span>
      </div>
    </div>
  );
}

