import React, { useState } from 'react';
import { CheckCircle, Circle, Code, Trophy, Zap } from 'lucide-react';

const CodingChallenges = () => {
  const [currentLevel, setCurrentLevel] = useState(1);
  const [completedChallenges, setCompletedChallenges] = useState(new Set());
  const [selectedLanguage, setSelectedLanguage] = useState('python');
  const [showSolution, setShowSolution] = useState({});

  const challenges = {
    1: {
      title: "Hello Coder",
      difficulty: "Beginner",
      description: "Write a function that takes a name and returns 'Hello, [name]!'",
      examples: ["hello('Alice') → 'Hello, Alice!'", "hello('Bob') → 'Hello, Bob!'"],
      solutions: {
        python: "def hello(name):\n    return f'Hello, {name}!'",
        javascript: "function hello(name) {\n    return `Hello, ${name}!`;\n}",
        java: "public static String hello(String name) {\n    return \"Hello, \" + name + \"!\";\n}"
      }
    },
    2: {
      title: "Sum of Evens",
      difficulty: "Beginner",
      description: "Write a function that returns the sum of all even numbers from 1 to n",
      examples: ["sum_evens(10) → 30 (2+4+6+8+10)", "sum_evens(5) → 6 (2+4)"],
      solutions: {
        python: "def sum_evens(n):\n    return sum(i for i in range(2, n+1, 2))",
        javascript: "function sumEvens(n) {\n    let sum = 0;\n    for (let i = 2; i <= n; i += 2) {\n        sum += i;\n    }\n    return sum;\n}",
        java: "public static int sumEvens(int n) {\n    int sum = 0;\n    for (int i = 2; i <= n; i += 2) {\n        sum += i;\n    }\n    return sum;\n}"
      }
    },
    3: {
      title: "Palindrome Checker",
      difficulty: "Intermediate",
      description: "Write a function that checks if a string is a palindrome (ignoring spaces and case)",
      examples: ["is_palindrome('racecar') → true", "is_palindrome('A man a plan a canal Panama') → true"],
      solutions: {
        python: "def is_palindrome(s):\n    clean = ''.join(s.lower().split())\n    return clean == clean[::-1]",
        javascript: "function isPalindrome(s) {\n    const clean = s.toLowerCase().replace(/\\s/g, '');\n    return clean === clean.split('').reverse().join('');\n}",
        java: "public static boolean isPalindrome(String s) {\n    String clean = s.toLowerCase().replaceAll(\"\\\\s\", \"\");\n    return clean.equals(new StringBuilder(clean).reverse().toString());\n}"
      }
    },
    4: {
      title: "Two Sum Problem",
      difficulty: "Intermediate",
      description: "Given an array of integers and a target sum, return indices of two numbers that add up to the target",
      examples: ["two_sum([2,7,11,15], 9) → [0,1]", "two_sum([3,2,4], 6) → [1,2]"],
      solutions: {
        python: "def two_sum(nums, target):\n    seen = {}\n    for i, num in enumerate(nums):\n        complement = target - num\n        if complement in seen:\n            return [seen[complement], i]\n        seen[num] = i\n    return []",
        javascript: "function twoSum(nums, target) {\n    const seen = new Map();\n    for (let i = 0; i < nums.length; i++) {\n        const complement = target - nums[i];\n        if (seen.has(complement)) {\n            return [seen.get(complement), i];\n        }\n        seen.set(nums[i], i);\n    }\n    return [];\n}",
        java: "public static int[] twoSum(int[] nums, int target) {\n    Map<Integer, Integer> seen = new HashMap<>();\n    for (int i = 0; i < nums.length; i++) {\n        int complement = target - nums[i];\n        if (seen.containsKey(complement)) {\n            return new int[]{seen.get(complement), i};\n        }\n        seen.put(nums[i], i);\n    }\n    return new int[]{};\n}"
      }
    },
    5: {
      title: "Binary Tree Depth",
      difficulty: "Advanced",
      description: "Find the maximum depth of a binary tree. Assume TreeNode class with left, right, and val properties.",
      examples: ["Tree: [3,9,20,null,null,15,7] → 3", "Tree: [1,null,2] → 2"],
      solutions: {
        python: "def max_depth(root):\n    if not root:\n        return 0\n    return 1 + max(max_depth(root.left), max_depth(root.right))",
        javascript: "function maxDepth(root) {\n    if (!root) return 0;\n    return 1 + Math.max(maxDepth(root.left), maxDepth(root.right));\n}",
        java: "public static int maxDepth(TreeNode root) {\n    if (root == null) return 0;\n    return 1 + Math.max(maxDepth(root.left), maxDepth(root.right));\n}"
      }
    },
    6: {
      title: "Longest Substring Without Repeating Characters",
      difficulty: "Advanced",
      description: "Find the length of the longest substring without repeating characters",
      examples: ["length_of_longest_substring('abcabcbb') → 3", "length_of_longest_substring('pwwkew') → 3"],
      solutions: {
        python: "def length_of_longest_substring(s):\n    seen = {}\n    start = max_len = 0\n    for i, char in enumerate(s):\n        if char in seen and seen[char] >= start:\n            start = seen[char] + 1\n        seen[char] = i\n        max_len = max(max_len, i - start + 1)\n    return max_len",
        javascript: "function lengthOfLongestSubstring(s) {\n    const seen = new Map();\n    let start = 0, maxLen = 0;\n    for (let i = 0; i < s.length; i++) {\n        if (seen.has(s[i]) && seen.get(s[i]) >= start) {\n            start = seen.get(s[i]) + 1;\n        }\n        seen.set(s[i], i);\n        maxLen = Math.max(maxLen, i - start + 1);\n    }\n    return maxLen;\n}",
        java: "public static int lengthOfLongestSubstring(String s) {\n    Map<Character, Integer> seen = new HashMap<>();\n    int start = 0, maxLen = 0;\n    for (int i = 0; i < s.length(); i++) {\n        if (seen.containsKey(s.charAt(i)) && seen.get(s.charAt(i)) >= start) {\n            start = seen.get(s.charAt(i)) + 1;\n        }\n        seen.put(s.charAt(i), i);\n        maxLen = Math.max(maxLen, i - start + 1);\n    }\n    return maxLen;\n}"
      }
    }
  };

  const handleComplete = (challengeId) => {
    setCompletedChallenges(prev => new Set([...prev, challengeId]));
    if (challengeId === currentLevel && currentLevel < Object.keys(challenges).length) {
      setCurrentLevel(prev => prev + 1);
    }
  };

  const toggleSolution = (challengeId) => {
    setShowSolution(prev => ({
      ...prev,
      [challengeId]: !prev[challengeId]
    }));
  };

  const getDifficultyColor = (difficulty) => {
    switch (difficulty) {
      case 'Beginner': return 'text-green-600 bg-green-100';
      case 'Intermediate': return 'text-orange-600 bg-orange-100';
      case 'Advanced': return 'text-red-600 bg-red-100';
      default: return 'text-gray-600 bg-gray-100';
    }
  };

  return (
    <div className="max-w-4xl mx-auto p-6 bg-gray-50 min-h-screen">
      <div className="bg-white rounded-lg shadow-lg p-6 mb-6">
        <div className="flex items-center gap-3 mb-4">
          <Trophy className="text-yellow-500" size={32} />
          <h1 className="text-3xl font-bold text-gray-800">Coding Challenges</h1>
        </div>

        <div className="flex items-center gap-4 mb-6">
          <div className="flex items-center gap-2">
            <Code className="text-blue-500" size={20} />
            <span className="text-gray-600">Language:</span>
            <select 
              value={selectedLanguage} 
              onChange={(e) => setSelectedLanguage(e.target.value)}
              className="px-3 py-1 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
            >
              <option value="python">Python</option>
              <option value="javascript">JavaScript</option>
              <option value="java">Java</option>
            </select>
          </div>

          <div className="flex items-center gap-2">
            <Zap className="text-yellow-500" size={20} />
            <span className="text-gray-600">Progress:</span>
            <span className="font-semibold text-blue-600">{completedChallenges.size}/{Object.keys(challenges).length}</span>
          </div>
        </div>
      </div>

      <div className="space-y-6">
        {Object.entries(challenges).map(([id, challenge]) => {
          const isCompleted = completedChallenges.has(parseInt(id));
          const isUnlocked = parseInt(id) <= currentLevel;

          return (
            <div 
              key={id} 
              className={`bg-white rounded-lg shadow-md p-6 transition-all duration-300 ${
                !isUnlocked ? 'opacity-50' : ''
              } ${isCompleted ? 'ring-2 ring-green-500' : ''}`}
            >
              <div className="flex items-start justify-between mb-4">
                <div className="flex items-center gap-3">
                  {isCompleted ? (
                    <CheckCircle className="text-green-500" size={24} />
                  ) : (
                    <Circle className="text-gray-400" size={24} />
                  )}
                  <div>
                    <h3 className="text-xl font-semibold text-gray-800">
                      Challenge {id}: {challenge.title}
                    </h3>
                    <span className={`inline-block px-2 py-1 rounded-full text-sm font-medium ${getDifficultyColor(challenge.difficulty)}`}>
                      {challenge.difficulty}
                    </span>
                  </div>
                </div>
                {!isUnlocked && (
                  <div className="text-sm text-gray-500 bg-gray-100 px-3 py-1 rounded-full">
                    Locked
                  </div>
                )}
              </div>

              {isUnlocked && (
                <>
                  <div className="mb-4">
                    <p className="text-gray-700 mb-3">{challenge.description}</p>
                    <div className="bg-gray-50 p-3 rounded-md">
                      <h4 className="font-medium text-gray-800 mb-2">Examples:</h4>
                      <ul className="text-sm text-gray-600 space-y-1">
                        {challenge.examples.map((example, idx) => (
                          <li key={idx} className="font-mono">{example}</li>
                        ))}
                      </ul>
                    </div>
                  </div>

                  <div className="flex gap-3">
                    <button
                      onClick={() => handleComplete(parseInt(id))}
                      disabled={isCompleted}
                      className={`px-4 py-2 rounded-md font-medium transition-colors ${
                        isCompleted 
                          ? 'bg-green-100 text-green-800 cursor-not-allowed' 
                          : 'bg-blue-500 text-white hover:bg-blue-600'
                      }`}
                    >
                      {isCompleted ? 'Completed!' : 'Mark Complete'}
                    </button>

                    <button
                      onClick={() => toggleSolution(parseInt(id))}
                      className="px-4 py-2 border border-gray-300 rounded-md text-gray-700 hover:bg-gray-50 transition-colors"
                    >
                      {showSolution[parseInt(id)] ? 'Hide Solution' : 'Show Solution'}
                    </button>
                  </div>

                  {showSolution[parseInt(id)] && (
                    <div className="mt-4 bg-gray-900 text-gray-100 p-4 rounded-md">
                      <h4 className="font-medium mb-2 text-gray-300">Solution ({selectedLanguage}):</h4>
                      <pre className="text-sm overflow-x-auto">
                        <code>{challenge.solutions[selectedLanguage]}</code>
                      </pre>
                    </div>
                  )}
                </>
              )}
            </div>
          );
        })}
      </div>

      {completedChallenges.size === Object.keys(challenges).length && (
        <div className="bg-gradient-to-r from-green-500 to-blue-500 text-white p-6 rounded-lg shadow-lg mt-6 text-center">
          <Trophy className="mx-auto mb-2" size={48} />
          <h2 className="text-2xl font-bold mb-2">Congratulations!</h2>
          <p>You've completed all challenges! Ready for more advanced problems?</p>
        </div>
      )}
    </div>
  );
};

export default CodingChallenges;

