from flask import Flask, jsonify, render_template
from flask_cors import CORS
import requests
from datetime import datetime, timedelta
import os

app = Flask(__name__)
CORS(app)

# Cache to avoid hitting APIs too frequently
cache = {}
CACHE_DURATION = timedelta(minutes=5)

def get_cached_or_fetch(key, fetch_function):
    """Simple caching mechanism"""
    if key in cache:
        data, timestamp = cache[key]
        if datetime.now() - timestamp < CACHE_DURATION:
            return data

    data = fetch_function()
    cache[key] = (data, datetime.now())
    return data

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/api/weather/<city>')
def get_weather(city):
    """Fetch weather data from OpenWeatherMap"""
    def fetch():
        API_KEY = os.getenv('OPENWEATHER_API_KEY', 'YOUR_API_KEY_HERE')
        url = f'http://api.openweathermap.org/data/2.5/weather?q={city}&appid={API_KEY}&units=metric'
        try:
            response = requests.get(url, timeout=5)
            response.raise_for_status()
            data = response.json()
            return {
                'success': True,
                'city': data['name'],
                'temperature': round(data['main']['temp']),
                'description': data['weather'][0]['description'],
                'icon': data['weather'][0]['icon'],
                'humidity': data['main']['humidity'],
                'wind_speed': data['wind']['speed']
            }
        except Exception as e:
            return {'success': False, 'error': str(e)}

    return jsonify(get_cached_or_fetch(f'weather_{city}', fetch))

@app.route('/api/joke')
def get_joke():
    """Fetch a programming joke"""
    def fetch():
        url = 'https://v2.jokeapi.dev/joke/Programming?type=single'
        try:
            response = requests.get(url, timeout=5)
            response.raise_for_status()
            data = response.json()
            return {
                'success': True,
                'joke': data.get('joke', 'No joke available')
            }
        except Exception as e:
            return {'success': False, 'error': str(e)}

    return jsonify(fetch())  # Don't cache jokes, we want fresh ones

@app.route('/api/nasa')
def get_nasa_apod():
    """Fetch NASA Astronomy Picture of the Day"""
    def fetch():
        API_KEY = os.getenv('NASA_API_KEY', 'DEMO_KEY')
        url = f'https://api.nasa.gov/planetary/apod?api_key={API_KEY}'
        try:
            response = requests.get(url, timeout=5)
            response.raise_for_status()
            data = response.json()
            return {
                'success': True,
                'title': data['title'],
                'date': data['date'],
                'explanation': data['explanation'],
                'url': data['url'],
                'media_type': data.get('media_type', 'image')
            }
        except Exception as e:
            return {'success': False, 'error': str(e)}

    return jsonify(get_cached_or_fetch('nasa_apod', fetch))

@app.route('/api/crypto')
def get_crypto():
    """Fetch cryptocurrency prices"""
    def fetch():
        url = 'https://api.coingecko.com/api/v3/simple/price?ids=bitcoin,ethereum,cardano&vs_currencies=usd&include_24hr_change=true'
        try:
            response = requests.get(url, timeout=5)
            response.raise_for_status()
            data = response.json()
            return {
                'success': True,
                'bitcoin': {
                    'price': data['bitcoin']['usd'],
                    'change': round(data['bitcoin']['usd_24h_change'], 2)
                },
                'ethereum': {
                    'price': data['ethereum']['usd'],
                    'change': round(data['ethereum']['usd_24h_change'], 2)
                },
                'cardano': {
                    'price': data['cardano']['usd'],
                    'change': round(data['cardano']['usd_24h_change'], 2)
                }
            }
        except Exception as e:
            return {'success': False, 'error': str(e)}

    return jsonify(get_cached_or_fetch('crypto', fetch))

if __name__ == '__main__':
    app.run(debug=True, port=5000)

