```javascript
// --- CHART RENDERING ---
let volumeChartInstance = null;
let severityChartInstance = null;

function renderCharts(rows) {
  renderVolumeChart(rows);
  renderSeverityChart(rows);
}

function renderVolumeChart(rows) {
  // Group alerts by date
  const dateCounts = {};

  rows.forEach(r => {
    const dateKey = r.date.toISOString().split('T')[0]; // YYYY-MM-DD
    dateCounts[dateKey] = (dateCounts[dateKey] || 0) + 1;
  });

  // Sort dates and get last 30 days
  const sortedDates = Object.keys(dateCounts).sort();
  const last30 = sortedDates.slice(-30);

  const labels = last30.map(d => {
    const date = new Date(d);
    return date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
  });

  const data = last30.map(d => dateCounts[d] || 0);

  const ctx = document.getElementById('volumeChart');
  if (!ctx) return;

  // Destroy existing chart
  if (volumeChartInstance) {
    volumeChartInstance.destroy();
  }

  // Determine colors based on theme
  const isDark = html.classList.contains('dark');
  const gridColor = isDark ? 'rgba(75, 85, 99, 0.3)' : 'rgba(229, 231, 235, 0.8)';
  const textColor = isDark ? 'rgba(156, 163, 175, 1)' : 'rgba(75, 85, 99, 1)';

  volumeChartInstance = new Chart(ctx, {
    type: 'line',
    data: {
      labels: labels,
      datasets: [{
        label: 'Alerts',
        data: data,
        borderColor: '#0ea5e9',
        backgroundColor: 'rgba(14, 165, 233, 0.1)',
        fill: true,
        tension: 0.4,
        pointRadius: 3,
        pointHoverRadius: 5
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: { display: false },
        tooltip: {
          callbacks: {
            label: (context) => ` ${context.parsed.y} alerts`
          }
        }
      },
      scales: {
        x: {
          grid: { display: false },
          ticks: { 
            color: textColor,
            maxRotation: 45,
            minRotation: 45
          }
        },
        y: {
          beginAtZero: true,
          ticks: { 
            color: textColor,
            precision: 0
          },
          grid: { color: gridColor }
        }
      }
    }
  });
}

function renderSeverityChart(rows) {
  // Count by severity
  const severityCounts = {
    critical: 0,
    high: 0,
    medium: 0,
    low: 0
  };

  rows.forEach(r => {
    const sev = r.severity.toLowerCase();
    if (severityCounts.hasOwnProperty(sev)) {
      severityCounts[sev]++;
    }
  });

  const labels = ['Critical', 'High', 'Medium', 'Low'];
  const data = [
    severityCounts.critical,
    severityCounts.high,
    severityCounts.medium,
    severityCounts.low
  ];

  const ctx = document.getElementById('severityChart');
  if (!ctx) return;

  // Destroy existing chart
  if (severityChartInstance) {
