const express = require('express');
const cors = require('cors');
const axios = require('axios');

const app = express();
const PORT = process.env.PORT || 3001;

// Configuration for your local LLM
const LLM_CONFIG = {
  // Toggle between 'ollama' and 'lmstudio'
  provider: 'ollama',

  // Ollama configuration
  ollama: {
    baseUrl: 'http://localhost:11434/api',
    model: 'llama2', // Change to your installed model
  },

  // LM Studio configuration (OpenAI-compatible API)
  lmstudio: {
    baseUrl: 'http://localhost:1234/v1',
    model: 'local-model', // LM Studio uses this as a placeholder
  }
};

// Middleware
app.use(cors()); // Enable CORS for React frontend
app.use(express.json()); // Parse JSON request bodies

// Logging middleware for debugging
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// Health check endpoint - useful for monitoring
app.get('/health', (req, res) => {
  res.json({ 
    status: 'healthy',
    timestamp: new Date().toISOString(),
    llmProvider: LLM_CONFIG.provider
  });
});

// Get available models endpoint
app.get('/api/models', async (req, res) => {
  try {
    if (LLM_CONFIG.provider === 'ollama') {
      const response = await axios.get(`${LLM_CONFIG.ollama.baseUrl.replace('/api', '')}/api/tags`);
      const models = response.data.models.map(m => ({
        name: m.name,
        size: m.size,
        modified: m.modified_at
      }));
      res.json({ models, provider: 'ollama' });
    } else {
      // LM Studio doesn't have a model list endpoint, return configured model
      res.json({ 
        models: [{ name: LLM_CONFIG.lmstudio.model }],
        provider: 'lmstudio'
      });
    }
  } catch (error) {
    console.error('Error fetching models:', error.message);
    res.status(500).json({ 
      error: 'Failed to fetch models',
      details: error.message 
    });
  }
});

// Main chat endpoint - this is where the magic happens
app.post('/api/chat', async (req, res) => {
  const { message, conversationHistory = [] } = req.body;

  // Validate request
  if (!message || typeof message !== 'string') {
    return res.status(400).json({ 
      error: 'Invalid request: message is required and must be a string' 
    });
  }

  console.log(`Processing message: "${message.substring(0, 50)}..."`);

  try {
    let aiResponse;

    if (LLM_CONFIG.provider === 'ollama') {
      // Ollama API call
      aiResponse = await sendToOllama(message, conversationHistory);
    } else {
      // LM Studio API call (OpenAI-compatible)
      aiResponse = await sendToLMStudio(message, conversationHistory);
    }

    res.json({
      response: aiResponse,
      timestamp: new Date().toISOString(),
      provider: LLM_CONFIG.provider
    });

  } catch (error) {
    console.error('Error processing chat:', error.message);

    // Provide helpful error messages
    let errorMessage = 'Failed to get response from AI';
    let statusCode = 500;

    if (error.code === 'ECONNREFUSED') {
      errorMessage = `Cannot connect to ${LLM_CONFIG.provider}. Make sure it's running on the configured port.`;
      statusCode = 503;
    } else if (error.response) {
      errorMessage = `AI service error: ${error.response.data?.error || error.message}`;
      statusCode = error.response.status;
    }

    res.status(statusCode).json({ 
      error: errorMessage,
      details: error.message,
      provider: LLM_CONFIG.provider
    });
  }
});

// Function to communicate with Ollama
async function sendToOllama(message, conversationHistory) {
  // Build conversation context
  const prompt = buildPromptFromHistory(conversationHistory, message);

  const response = await axios.post(
    `${LLM_CONFIG.ollama.baseUrl}/generate`,
    {
      model: LLM_CONFIG.ollama.model,
      prompt: prompt,
      stream: false, // Set to true if you want streaming responses
      options: {
        temperature: 0.7,
        top_p: 0.9,
        top_k: 40,
      }
    },
    {
      timeout: 60000, // 60 second timeout
      headers: { 'Content-Type': 'application/json' }
    }
  );

  return response.data.response;
}

// Function to communicate with LM Studio (OpenAI-compatible API)
async function sendToLMStudio(message, conversationHistory) {
  // Build messages array in OpenAI format
  const messages = [
    {
      role: 'system',
      content: 'You are a helpful AI assistant running locally.'
    },
    // Add conversation history
    ...conversationHistory.map(msg => ({
      role: msg.sender === 'user' ? 'user' : 'assistant',
      content: msg.text
    })),
    // Add current message
    {
      role: 'user',
      content: message
    }
  ];

  const response = await axios.post(
    `${LLM_CONFIG.lmstudio.baseUrl}/chat/completions`,
    {
      model: LLM_CONFIG.lmstudio.model,
      messages: messages,
      temperature: 0.7,
      max_tokens: 1000,
      stream: false
    },
    {
      timeout: 60000,
      headers: { 
        'Content-Type': 'application/json',
        'Authorization': 'Bearer lm-studio' // LM Studio doesn't require real auth
      }
    }
  );

  return response.data.choices[0].message.content;
}

// Helper function to build prompt from conversation history
function buildPromptFromHistory(history, currentMessage) {
  let prompt = '';

  // Add conversation context (limit to last 10 messages to avoid token limits)
  const recentHistory = history.slice(-10);

  for (const msg of recentHistory) {
    if (msg.sender === 'user') {
      prompt += `User: ${msg.text}\n`;
    } else {
      prompt += `Assistant: ${msg.text}\n`;
    }
  }

  // Add current message
  prompt += `User: ${currentMessage}\nAssistant:`;

  return prompt;
}

// Streaming endpoint (optional - for real-time responses)
app.post('/api/chat/stream', async (req, res) => {
  const { message } = req.body;

  if (!message) {
    return res.status(400).json({ error: 'Message is required' });
  }

  // Set headers for Server-Sent Events
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');

  try {
    if (LLM_CONFIG.provider === 'ollama') {
      // Stream from Ollama
      const response = await axios.post(
        `${LLM_CONFIG.ollama.baseUrl}/generate`,
        {
          model: LLM_CONFIG.ollama.model,
          prompt: message,
          stream: true
        },
        {
          responseType: 'stream'
        }
      );

      response.data.on('data', (chunk) => {
        const data = JSON.parse(chunk.toString());
        res.write(`data: ${JSON.stringify({ text: data.response })}\n\n`);
      });

      response.data.on('end', () => {
        res.write('data: [DONE]\n\n');
        res.end();
      });
    } else {
      res.status(501).json({ error: 'Streaming not implemented for LM Studio' });
    }
  } catch (error) {
    console.error('Streaming error:', error.message);
    res.write(`data: ${JSON.stringify({ error: error.message })}\n\n`);
    res.end();
  }
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({ 
    error: 'Internal server error',
    details: err.message 
  });
});

// Start the server
app.listen(PORT, () => {
  console.log(`\n🚀 AI Chatbot Backend Server Started`);
  console.log(`━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━`);
  console.log(`Server: http://localhost:${PORT}`);
  console.log(`Health: http://localhost:${PORT}/health`);
  console.log(`LLM Provider: ${LLM_CONFIG.provider}`);
  console.log(`━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n`);

  // Test LLM connection on startup
  testLLMConnection();
});

// Function to test LLM connectivity
async function testLLMConnection() {
  try {
    if (LLM_CONFIG.provider === 'ollama') {
      await axios.get(`${LLM_CONFIG.ollama.baseUrl.replace('/api', '')}/api/tags`);
      console.log(`✓ Successfully connected to Ollama`);
    } else {
      console.log(`⚠ LM Studio connection test skipped (no health endpoint)`);
