  console.log(`Processing message: "${message.substring(0, 50)}..."`);

  try {
    let aiResponse;

    if (LLM_CONFIG.provider === 'ollama') {
      aiResponse = await sendToOllama(message, conversationHistory);
    } else {
      aiResponse = await sendToLMStudio(message, conversationHistory);
    }

    res.json({
      response: aiResponse,
      timestamp: new Date().toISOString(),
      provider: LLM_CONFIG.provider
    });

  } catch (error) {
    console.error('Error processing chat:', error.message);

    let errorMessage = 'Failed to get response from AI';
    let statusCode = 500;

    if (error.code === 'ECONNREFUSED') {
      errorMessage = `Cannot connect to ${LLM_CONFIG.provider}. Make sure it's running on the configured port.`;
      statusCode = 503;
    } else if (error.response) {
      errorMessage = `AI service error: ${error.response.data?.error || error.message}`;
      statusCode = error.response.status;
    }

    res.status(statusCode).json({ 
      error: errorMessage,
      details: error.message,
      provider: LLM_CONFIG.provider
    });
  }
});

// STREAMING ENDPOINT - Main feature for real-time responses
app.post('/api/chat/stream', async (req, res) => {
  const { message, conversationHistory = [] } = req.body;

  if (!message || typeof message !== 'string') {
    return res.status(400).json({ 
      error: 'Invalid request: message is required' 
    });
  }

  console.log(`Streaming message: "${message.substring(0, 50)}..."`);

  // Set headers for Server-Sent Events
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.setHeader('X-Accel-Buffering', 'no'); // Disable nginx buffering

  // Send initial connection confirmation
  res.write(`data: ${JSON.stringify({ type: 'connected' })}\n\n`);

  try {
    if (LLM_CONFIG.provider === 'ollama') {
      await streamFromOllama(message, conversationHistory, res);
    } else {
      await streamFromLMStudio(message, conversationHistory, res);
    }
  } catch (error) {
    console.error('Streaming error:', error.message);
    res.write(`data: ${JSON.stringify({ 
      type: 'error', 
      error: error.message 
    })}\n\n`);
  } finally {
    // Send completion signal
    res.write(`data: ${JSON.stringify({ type: 'done' })}\n\n`);
    res.end();
  }
});

// Stream responses from Ollama
async function streamFromOllama(message, conversationHistory, res) {
  const prompt = buildPromptFromHistory(conversationHistory, message);

  const response = await axios.post(
    `${LLM_CONFIG.ollama.baseUrl}/generate`,
    {
      model: LLM_CONFIG.ollama.model,
      prompt: prompt,
      stream: true,
      options: {
        temperature: 0.7,
        top_p: 0.9,
        top_k: 40,
      }
    },
    {
      responseType: 'stream',
      timeout: 120000 // 2 minute timeout for long responses
    }
  );

  // Process each chunk as it arrives
  return new Promise((resolve, reject) => {
    response.data.on('data', (chunk) => {
      try {
        const lines = chunk.toString().split('\n').filter(line => line.trim());

        for (const line of lines) {
          const data = JSON.parse(line);

          if (data.response) {
            // Send each token to the client
            res.write(`data: ${JSON.stringify({ 
              type: 'token', 
              content: data.response 
            })}\n\n`);
          }

          // Check if this is the final chunk
          if (data.done) {
            resolve();
          }
        }
      } catch (parseError) {
        console.error('Error parsing chunk:', parseError);
      }
    });

    response.data.on('error', (error) => {
      reject(error);
    });

    response.data.on('end', () => {
      resolve();
    });
  });
}

// Stream responses from LM Studio (OpenAI-compatible)
async function streamFromLMStudio(message, conversationHistory, res) {
  const messages = [
    {
      role: 'system',
      content: 'You are a helpful AI assistant running locally.'
    },
    ...conversationHistory.map(msg => ({
      role: msg.sender === 'user' ? 'user' : 'assistant',
      content: msg.text
    })),
    {
      role: 'user',
      content: message
    }
  ];

  const response = await axios.post(
    `${LLM_CONFIG.lmstudio.baseUrl}/chat/completions`,
    {
      model: LLM_CONFIG.lmstudio.model,
      messages: messages,
      temperature: 0.7,
      max_tokens: 2000,
      stream: true // Enable streaming
    },
    {
      responseType: 'stream',
      timeout: 120000,
      headers: { 
        'Content-Type': 'application/json',
        'Authorization': 'Bearer lm-studio'
      }
    }
  );

  return new Promise((resolve, reject) => {
    let buffer = '';

    response.data.on('data', (chunk) => {
      try {
        buffer += chunk.toString();
        const lines = buffer.split('\n');

        // Keep the last incomplete line in the buffer
        buffer = lines.pop() || '';

        for (const line of lines) {
          const trimmedLine = line.trim();

          if (trimmedLine === '' || trimmedLine === 'data: [DONE]') {
            continue;
          }

          if (trimmedLine.startsWith('data: ')) {
            const jsonStr = trimmedLine.substring(6);

            try {
              const data = JSON.parse(jsonStr);
              const content = data.choices?.[0]?.delta?.content;

              if (content) {
                res.write(`data: ${JSON.stringify({ 
                  type: 'token', 
                  content: content 
                })}\n\n`);
              }
            } catch (parseError) {
              // Skip malformed JSON
            }
          }
        }
      } catch (error) {
        console.error('Error processing chunk:', error);
      }
    });

    response.data.on('error', (error) => {
      reject(error);
    });

    response.data.on('end', () => {
      resolve();
    });
  });
}

